sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    var min = g_form.getValue('u_min_value');
    var max = g_form.getValue('max_value');

    var nmax = max.replace(/[^0-9.-]/g, '');
    var nmin = min.replace(/[^0-9.-]/g, '');

    var maxi = parseFloat(nmax);
	var mini =  parseFloat(nmin);

	if (maxi < mini) { 
        g_form.addErrorMessage('Max Value Cannot Be less than min'); 


        g_form.setValue('u_min_value', ''); 
		  g_form.setValue('max_value', ''); 
    }





}
